"use client";

import { useId, useState, type ComponentPropsWithoutRef } from "react";

import { useThemeWipe } from "./use-theme-wipe";

export type ThemeToggleMode = "light" | "dark";

export interface ThemeToggleProps extends Omit<
  ComponentPropsWithoutRef<"button">,
  "children"
> {
  theme?: ThemeToggleMode;
  defaultTheme?: ThemeToggleMode;
  onThemeChange?: (theme: ThemeToggleMode) => void;
  size?: number;
  /** Opt in to a document reveal. onThemeChange must apply the theme synchronously. */
  pageTransition?: "none" | "circular";
}

const morph =
  "origin-center [transform-box:view-box] transition-[transform,opacity] duration-[420ms] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none";

export function ThemeToggle({
  theme,
  defaultTheme = "light",
  onThemeChange,
  size = 48,
  pageTransition = "none",
  disabled,
  className = "",
  style,
  onClick,
  type = "button",
  "aria-label": label,
  ...props
}: ThemeToggleProps) {
  const [localTheme, setLocalTheme] = useState(defaultTheme);
  const currentTheme = theme ?? localTheme;
  const wipe = useThemeWipe();
  const dark = currentTheme === "dark";
  const maskId = `theme-toggle-${useId().replaceAll(":", "")}`;

  return (
    <button
      {...props}
      type={type}
      disabled={disabled}
      aria-label={label ?? `Switch to ${dark ? "light" : "dark"} mode`}
      aria-pressed={dark}
      data-theme-toggle={currentTheme}
      className={`inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full border-0 bg-white p-0 text-black transition-[background-color,color,scale] duration-200 hover:scale-[1.04] active:scale-95 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:scale-100 data-[theme-toggle=dark]:bg-black data-[theme-toggle=dark]:text-white motion-reduce:transition-none motion-reduce:hover:scale-100 motion-reduce:active:scale-100 ${pageTransition === "circular" ? "hover:scale-100! active:scale-100!" : ""} ${className}`}
      style={{
        width: size,
        height: size,
        minWidth: 44,
        minHeight: 44,
        ...style,
      }}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        wipe(
          event.currentTarget,
          currentTheme,
          pageTransition,
          (next) => {
            if (theme === undefined) setLocalTheme(next);
            onThemeChange?.(next);
          },
          props.nonce,
        );
      }}
    >
      <svg
        aria-hidden="true"
        focusable="false"
        viewBox="0 0 32 32"
        className="size-2/3 overflow-visible"
      >
        <defs>
          <mask
            id={maskId}
            maskUnits="userSpaceOnUse"
            x="0"
            y="0"
            width="32"
            height="32"
          >
            <rect width="32" height="32" fill="white" />
            <circle
              data-theme-toggle-cutout=""
              cx="36"
              cy="-4"
              r="8"
              fill="black"
              className={morph}
              style={{
                transform: dark
                  ? "translate(-16px, 16px)"
                  : "translate(0px, 0px)",
              }}
            />
          </mask>
        </defs>
        <g mask={`url(#${maskId})`}>
          <circle
            cx="16"
            cy="16"
            r="7.5"
            fill="currentColor"
            className={morph}
            style={{ transform: dark ? "scale(1.2)" : "scale(1)" }}
          />
        </g>
        <g
          data-theme-toggle-rays=""
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
          className={morph}
          style={{
            opacity: dark ? 0 : 1,
            transform: dark
              ? "rotate(45deg) scale(0.5)"
              : "rotate(0deg) scale(1)",
          }}
        >
          {Array.from({ length: 8 }, (_, index) => (
            <line
              key={index}
              x1="16"
              y1="2"
              x2="16"
              y2="6"
              transform={`rotate(${index * 45} 16 16)`}
            />
          ))}
        </g>
      </svg>
    </button>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { flushSync } from "react-dom";

type Mode = "light" | "dark";
type ActiveWipe = { mode: Mode; cancel: () => void };

// A document can have only one view transition, even with several toggles.
const activeWipes = new WeakMap<Document, ActiveWipe>();
const styles = `
html[data-theme-wipe]::view-transition { pointer-events: none; }
html[data-theme-wipe]::view-transition-group(*) { animation: none; }
html[data-theme-wipe]::view-transition-old(root),
html[data-theme-wipe]::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}`;

export function useThemeWipe() {
  const owned = useRef<ActiveWipe | null>(null);
  useEffect(() => () => owned.current?.cancel(), []);

  return (
    origin: HTMLElement,
    current: Mode,
    effect: "none" | "circular",
    change: (mode: Mode) => void,
    nonce?: string,
  ) => {
    const doc = origin.ownerDocument;
    const win = doc.defaultView;
    const previous = activeWipes.get(doc);
    const mode = (previous?.mode ?? current) === "dark" ? "light" : "dark";
    previous?.cancel();
    let applied = false;
    const apply = () => {
      if (applied) return;
      applied = true;
      flushSync(() => change(mode));
    };
    const reduced = win?.matchMedia("(prefers-reduced-motion: reduce)");
    if (
      effect === "none" ||
      previous ||
      !win ||
      reduced?.matches ||
      doc.visibilityState === "hidden" ||
      !doc.startViewTransition ||
      // Do not interrupt a router-owned transition on browsers exposing it.
      (doc as Document & { activeViewTransition?: ViewTransition | null })
        .activeViewTransition
    ) {
      apply();
      return;
    }

    const root = doc.documentElement;
    const bounds = origin.getBoundingClientRect();
    const x = bounds.left + bounds.width / 2;
    const y = bounds.top + bounds.height / 2;
    const radius = Math.hypot(
      Math.max(x, win.innerWidth - x),
      Math.max(y, win.innerHeight - y),
    );
    // Ship scoped transition CSS with the helper, not the app's stylesheet.
    const sheet = doc.createElement("style");
    if (nonce) sheet.nonce = nonce;
    sheet.textContent = styles;
    doc.head.append(sheet);
    if (!sheet.sheet) {
      sheet.remove();
      apply();
      return;
    }
    const oldAttribute = root.getAttribute("data-theme-wipe");
    let cancelled = false;
    let transition: ViewTransition | undefined;
    let animation: Animation | undefined;
    const cleanup = () => {
      animation?.cancel();
      sheet.remove();
      reduced?.removeEventListener("change", settle);
      win.removeEventListener("resize", settle);
      doc.removeEventListener("visibilitychange", visibility);
      if (activeWipes.get(doc) === run) {
        activeWipes.delete(doc);
        if (oldAttribute === null) root.removeAttribute("data-theme-wipe");
        else root.setAttribute("data-theme-wipe", oldAttribute);
      }
      if (owned.current === run) owned.current = null;
    };
    const run: ActiveWipe = {
      mode,
      cancel() {
        cancelled = true;
        transition?.skipTransition();
        cleanup();
      },
    };
    function settle() {
      run.cancel();
      apply();
    }
    function visibility() {
      if (doc.visibilityState === "hidden") settle();
    }
    owned.current = run;
    activeWipes.set(doc, run);
    root.setAttribute("data-theme-wipe", "");
    reduced?.addEventListener("change", settle);
    win.addEventListener("resize", settle);
    doc.addEventListener("visibilitychange", visibility);

    try {
      transition = doc.startViewTransition(() => {
        if (!cancelled) apply();
      });
      if (cancelled) transition.skipTransition();
      void transition.ready
        .then(() => {
          if (cancelled) return;
          animation = root.animate(
            {
              clipPath: [
                `circle(0px at ${x}px ${y}px)`,
                `circle(${radius}px at ${x}px ${y}px)`,
              ],
            },
            {
              duration: 620,
              easing: "cubic-bezier(0.65, 0, 0.35, 1)",
              pseudoElement: "::view-transition-new(root)",
            },
          );
        })
        .catch(() => {
          if (!cancelled) settle();
        });
      void transition.finished.then(cleanup, cleanup);
    } catch {
      settle();
    }
  };
}

